def transform(grid):
    g=[row[:] for row in grid]
    h,w=len(g),len(g[0])
    seen=set(); frames=[]
    for r in range(h):
        for c in range(w):
            color=g[r][c]
            if not color or (r,c) in seen:
                continue
            q=[(r,c)]; seen.add((r,c)); cells=[]
            while q:
                x,y=q.pop(); cells.append((x,y))
                for nx,ny in ((x-1,y),(x+1,y),(x,y-1),(x,y+1)):
                    if 0<=nx<h and 0<=ny<w and (nx,ny) not in seen and g[nx][ny]==color:
                        seen.add((nx,ny)); q.append((nx,ny))
            r0=min(x for x,y in cells); r1=max(x for x,y in cells)
            c0=min(y for x,y in cells); c1=max(y for x,y in cells)
            height,width=r1-r0+1,c1-c0+1
            if height<4 or width<4 or len(cells)!=2*height+2*width-4:
                continue
            if all(g[r0][y]==color and g[r1][y]==color for y in range(c0,c1+1)) and all(g[x][c0]==color and g[x][c1]==color for x in range(r0,r1+1)):
                frames.append((color,r0,r1,c0,c1))
    frame_cells={(r,c) for color,r0,r1,c0,c1 in frames for r in range(r0,r1+1) for c in range(c0,c1+1) if r in (r0,r1) or c in (c0,c1)}
    counts=Counter(g[r][c] for r in range(h) for c in range(w) if g[r][c] and (r,c) not in frame_cells)
    out=[[0]*w for _ in range(h)]
    for color,r0,r1,c0,c1 in frames:
        for r in range(r0,r1+1):
            for c in range(c0,c1+1):
                if r in (r0,r1) or c in (c0,c1):
                    out[r][c]=color
        inside_count=sum(1 for r in range(r0+1,r1) for c in range(c0+1,c1) if (r-r0-1+c-c0-1)%2==0)
        paint=next((x for x,n in counts.items() if n==inside_count),None)
        if paint is not None:
